#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_map<long long, int> count;
    for (int i = 0; i < n; i++) count[a[i]]++;
    int best = 0;
    for (auto& entry : count) {
        auto it = count.find(entry.first + 1);
        if (it != count.end()) best = max(best, entry.second + it->second);
    }
    cout << best << "\n";

    return 0;
}

code.java:
import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        Map<Long, Integer> count = new HashMap<>();
        for (int i = 0; i < n; i++) count.merge(a[i], 1, Integer::sum);
        int best = 0;
        for (Map.Entry<Long, Integer> entry : count.entrySet()) {
            Integer next = count.get(entry.getKey() + 1);
            if (next != null) best = Math.max(best, entry.getValue() + next);
        }
        System.out.println(best);
    }
}
